import { extractChaptersFromHtml } from './notaContent.js';
import { stripBlockPlain } from './blockPlainText.js';

/** Default title for newly created notas — auto-generation only while this value is unchanged. */
export const DEFAULT_NOTA_TITLE = 'Nieuwe Concept Nota';
/** Longest title an auteur can give a nota: the input stops there and `saveTitle` cuts anything pasted beyond it. */
export const MAX_NOTA_TITLE_LENGTH = 120;

/** Maximum words for auto-generated nota titles. */
export const MAX_AUTO_TITLE_WORDS = 5;

/** Minimum plain-text length in the first chapter before title generation may run. */
const MIN_SUBSTANTIVE_CHARS = 15;

/** Placeholder phrases from template guidelines (italic instructions). */
const PLACEHOLDER_PATTERNS = [
    /^schrijf hier een korte, krachtige titel\.?$/i,
    /^start met typen\.{0,3}$/i
];

/**
 * Whether `text` is one of the generic placeholder phrases: the italic instruction of the first chapter, the editor's own prompt.
 * @param {string|null|undefined} text
 * @returns {boolean}
 */
export function isTemplatePlaceholderText(text) {
    const t = String(text || '').replace(/\s+/g, ' ').trim();
    return PLACEHOLDER_PATTERNS.some((re) => re.test(t));
}

/**
 * Whether auto title generation is allowed for this nota.
 * Legacy notas without `titleManuallySet` are treated as manual when title ≠ default.
 * @param {{ title?: string, titleManuallySet?: boolean }|null|undefined} nota
 */
export function isTitleAutoGenEligible(nota) {
    if (!nota) return false;
    if (nota.titleManuallySet === true) return false;
    const title = (nota.title || '').trim();
    if (title !== DEFAULT_NOTA_TITLE) return false;
    return true;
}

/**
 * True when the first chapter has enough user-written text (not just template placeholders).
 * @param {string|null|undefined} htmlContent
 */
export function hasSubstantiveContentForTitle(htmlContent) {
    const chapters = extractChaptersFromHtml(htmlContent);
    const first = chapters[0];
    if (!first) return false;

    let plain = stripBlockPlain(first.content || '');
    for (const pattern of PLACEHOLDER_PATTERNS) {
        plain = plain.replace(pattern, '').trim();
    }
    plain = plain.replace(/\s+/g, ' ').trim();
    return plain.length >= MIN_SUBSTANTIVE_CHARS;
}

/**
 * Chapters payload for `/generate-nota-title` (first blocks with content, capped).
 * @param {string|null|undefined} htmlContent
 * @param {number} [maxChapters]
 */
export function chaptersForTitleGeneration(htmlContent, maxChapters = 3) {
    return extractChaptersFromHtml(htmlContent)
        .filter((c) => (c.content || '').trim())
        .slice(0, maxChapters);
}

/**
 * Sanitize an auto-generated title: first line, no quotes, max word count.
 * @param {string|null|undefined} title
 * @param {number} [maxWords]
 */
export function clampAutoGeneratedTitle(title, maxWords = MAX_AUTO_TITLE_WORDS) {
    let line = (title || '').trim().split('\n')[0].trim();
    for (const quote of ['"', "'", '«', '»', '“', '”', '„']) {
        if (line.startsWith(quote) && line.endsWith(quote) && line.length > 2) {
            line = line.slice(1, -1).trim();
        }
    }
    line = line.replace(/[.!?;:]+$/u, '');
    const words = line.split(/\s+/u).filter(Boolean);
    return words.slice(0, maxWords).join(' ');
}
